package br.com.archlab.api;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.test.context.SpringBootTest;import tools.jackson.databind.JsonNode;import tools.jackson.databind.json.JsonMapper;import java.nio.file.*;import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
/** Full HTTP stack and production core, without mocks. Artifacts are schema-checked independently. */
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
class V3PublicContractTest {
    @Value("$"+"{local.server.port}") int port;private final JsonMapper json=JsonMapper.builder().build();private final HttpClient client=HttpClient.newHttpClient();
    String input() throws Exception{return Files.readString(Path.of("../../docs/examples/v3/ce-ref-01-request.json"));}
    HttpResponse<String> post(String path,String body,String contentType) throws Exception {return client.send(HttpRequest.newBuilder(URI.create("http://localhost:"+port+"/api/v3/"+path)).header("Content-Type",contentType).POST(HttpRequest.BodyPublishers.ofString(body,StandardCharsets.UTF_8)).build(),HttpResponse.BodyHandlers.ofString());}
    HttpResponse<String> post(String path,String body) throws Exception{return post(path,body,"application/json");}
    JsonNode body(HttpResponse<String> response,int status) throws Exception{assertEquals(status,response.statusCode(),response.body());return json.readTree(response.body());}
    void artifact(String name,HttpResponse<String> response) throws Exception{Files.createDirectories(Path.of("target/v3-http"));Files.writeString(Path.of("target/v3-http/"+name+".json"),response.body());}
    @Test void allThreeValidatorsReturn200ForValidAndSemanticallyInvalidInputs() throws Exception {var request=json.readTree(input());String architecture=json.writeValueAsString(request.get("architecture"));var valid=post("architectures/validate",architecture);assertTrue(body(valid,200).get("valid").booleanValue());artifact("architecture-valid",valid);var invalid=post("architectures/validate",architecture.replace("DATABASE_GENERIC","UNKNOWN_DATABASE"));assertFalse(body(invalid,200).get("valid").booleanValue());artifact("architecture-invalid",invalid);
        String plan=json.writeValueAsString(request.at("/architecture/executionPlans/0"));String candidate="{\"architecture\":"+architecture+",\"executionPlan\":"+plan+"}";assertTrue(body(post("execution-plans/validate",candidate),200).get("valid").booleanValue());var bad=post("execution-plans/validate",candidate.replace("\"entryStepId\":\"pre\"","\"entryStepId\":\"missing\""));assertFalse(body(bad,200).get("valid").booleanValue());artifact("plan-invalid",bad);
        assertTrue(body(post("scenarios/validate",input()),200).get("valid").booleanValue());var scenario=post("scenarios/validate",input().replace("\"componentId\": \"client\"","\"componentId\": \"missing\""));assertFalse(body(scenario,200).get("valid").booleanValue());artifact("scenario-invalid",scenario);}
    @Test void invalidSimulationIs422WithStructuredViolations() throws Exception{var response=post("simulations",input().replace("\"componentId\": \"client\"","\"componentId\": \"missing\""));var result=body(response,422);assertEquals("SIMULATION_INVALID",result.get("code").asText());assertTrue(result.get("violations").size()>0);assertEquals("application/problem+json",response.headers().firstValue("content-type").orElseThrow());artifact("invalid-simulation",response);}
    @Test void validSimulationUsesAllSixComponentsAndSeparatesPrincipalFromGlobal() throws Exception{var response=post("simulations",input());var result=body(response,200);assertEquals(120,result.at("/principal/responseDurationMs").longValue());assertEquals(210,result.at("/global/completionDurationMs").longValue());assertEquals(6,result.at("/metrics/components").size());assertEquals("COMPLETED",result.at("/global/status").asText());artifact("ce-ref-01",response);assertEquals(result,body(post("simulations",input()),200));}
    @Test void simulatedFailureIsHttp200AndInvalidPolicyIsNotExecuted() throws Exception{String request=input().replace("\"initialStates\": []","\"initialStates\": [{\"kind\":\"COMPONENT\",\"componentId\":\"db\",\"available\":false}]");var response=post("simulations",request);assertEquals("FAILED",body(response,200).at("/principal/status").asText());artifact("simulated-failure",response);String invalid=input().replace("\"consumerEndpointId\"","\"unimplementedQueueProperty\"");assertEquals(422,post("simulations",invalid).statusCode());}
    @Test void horizonStopsWithPartialWorkAndOpenTimelineIntervals() throws Exception{String request=input().replace("\"completionMode\": \"DRAIN_ALL\"","\"completionMode\":\"UNTIL_HORIZON\",\"horizonAtMs\":150");var response=post("simulations",request);var result=body(response,200);assertEquals("HORIZON_REACHED",result.at("/global/status").asText());assertTrue(result.at("/global/completionAtMs").isNull());assertEquals(150,result.at("/global/observedUntilMs").longValue());assertTrue(result.at("/global/pendingWork").size()>0);artifact("horizon-150",response);}
    @Test void malformedTypesUnknownFieldsAndUnsupportedMediaAreTransportErrors() throws Exception{artifact("malformed",post("simulations","{"));assertEquals(400,post("simulations","{").statusCode());assertEquals(400,post("simulations",input().replace("\"seed\": 7","\"seed\":\"7\"")).statusCode());assertEquals(400,post("simulations",input().replace("\"seed\": 7","\"seed\":7,\"unknown\":true")).statusCode());var response=post("simulations",input(),"text/plain");assertEquals(415,response.statusCode());artifact("unsupported-media",response);}
    @Test void oversizedBodiesAreRejectedWithAndWithoutContentLength() throws Exception{String payload=" ".repeat(1024*1024+1);var response=post("simulations",payload);body(response,413);artifact("too-large",response);var chunked=HttpRequest.newBuilder(URI.create("http://localhost:"+port+"/api/v3/simulations")).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofInputStream(()->new java.io.ByteArrayInputStream(payload.getBytes(StandardCharsets.UTF_8)))).build();assertEquals(413,client.send(chunked,HttpResponse.BodyHandlers.ofString()).statusCode());}

    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(longs={0,10,50,119})
    void partialPrincipalBeforeResponseHasNoInventedTerminalTimes(long horizon) throws Exception{String request=input().replace("\"completionMode\": \"DRAIN_ALL\"","\"completionMode\":\"UNTIL_HORIZON\",\"horizonAtMs\":"+horizon);var response=post("simulations",request);var result=body(response,200);assertEquals("HORIZON_REACHED",result.at("/global/status").asText());assertEquals("IN_PROGRESS",result.at("/principal/status").asText());assertTrue(result.at("/principal/terminalAtMs").isNull());assertTrue(result.at("/metrics/principalResponseDurationMs").isNull());assertEquals(horizon,result.at("/metrics/observationDurationMs").longValue());artifact("horizon-"+horizon,response);}
}
